import type { NextConfig } from "next";

const nextConfig: NextConfig = {
  // Tailwind support for Turbopack (generated by create-next-app, keep it)
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },

  // Sends /api/v1/... from the browser to your Spring Boot backend,
  // so the login cookie belongs to the same site as your pages.
  async rewrites() {
    return [
      {
        source: "/api/v1/:path*",
        destination: `${process.env.BACKEND_URL || "http://localhost:8080"}/api/v1/:path*`,
      },
    ];
  },
};

export default nextConfig;